"""Buildless offline comparison dashboard with embedded evidence."""
import html
import json
import pandas as pd

def dashboard(out,monthly,annual,scores,metrics,now,loadings,signals,sources):
    historical=pd.read_csv(out.parents[0]/'current/matched_forecasts.csv')
    historical=historical.loc[historical.model.isin(['PHASE6C_DFM','U_MIDAS','COMBO_50_50'])]
    def records(frame): return json.loads(frame.to_json(orient='records'))
    data=dict(monthly=records(monthly),annual=records(annual),scores=records(scores),metrics=records(metrics),now=records(now),loadings=records(loadings),signals=records(signals),sources=records(sources),history=records(historical))
    text='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phase 7A · Electricity evidence</title>
<style>:root{font-family:Segoe UI,Arial;color:#e4edf7;background:#081322}body{max-width:1440px;margin:auto;padding:28px}h1{font-size:32px}h2{font-size:19px}p{line-height:1.6;color:#afc1d7}.banner{border-left:5px solid #ffbf69;padding:18px;background:#263044}article{background:#122239;border:1px solid #29415c;border-radius:14px;padding:20px;overflow:auto}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:20px}.kpi{display:flex;gap:28px;flex-wrap:wrap;margin:24px 0}.kpi strong{display:block;font-size:28px;color:#58d9cc}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:9px;border-bottom:1px solid #2b4058}a{color:#58d9cc}button,select{background:#1c3553;border:1px solid #47627d;color:white;padding:9px;border-radius:6px}svg{width:100%;height:220px}text{fill:#c7d4e5;font-size:12px}.empty{padding:30px;border:1px dashed #526175;color:#ffc985}details{margin-top:16px}@media(max-width:800px){.grid{grid-template-columns:1fr}body{padding:16px}}.bar{fill:#58d9cc}.tip{font-size:12px}</style>
<header><p>UZBEKISTAN GDP NOWCASTING / RESEARCH ONLY</p><h1>Electricity: evidence before estimation</h1><div class="banner"><strong>PHASE7A_INSUFFICIENT_DATA</strong><p>Three national monthly levels. Zero verified YoY pairs. E1 and C1 cannot be estimated; no production promotion.</p></div></header>
<div class="kpi"><div><strong>3 / 93</strong>Monthly coverage</div><div><strong>90</strong>Missing months</div><div><strong>0</strong>Matched challenger origins</div><div><strong>8.180901340616275%</strong>Frozen production 2026Q3</div></div>
<nav><button onclick="document.querySelectorAll('details').forEach(x=>x.open=!x.open)">Toggle evidence tables</button> <a href="phase7a_results.md">Detailed report</a> · <a href="source_registry.csv">Source registry</a> · <a href="run_manifest.json">Run manifest</a></nav>
<div class="grid">
<article><h2>A · Model comparison summary</h2><p>Scores below describe frozen production holdout benchmarks, 12 origins / four quarters. Challenger comparison is not estimable.</p><div id="summary"></div></article>
<article><h2>B · Pooled RMSE</h2><p>GDP percentage points. Frozen baseline only; E1/C1 metrics unavailable.</p><div id="rmse"></div></article>
<article><h2>C · Horizon accuracy</h2><select id="horizon" onchange="horizons()"><option>H1</option><option>H2</option><option>H3</option></select><div id="hchart"></div></article>
<article><h2>D · Actual versus predicted GDP</h2><p>Published cumulative YTD real GDP YoY %, quarterly target. Frozen historical forecasts.</p><select id="histH" onchange="history()"><option>H1</option><option>H2</option><option>H3</option></select><div id="history"></div></article>
<article><h2>E · Electricity consumption</h2><p>Republic system consumption, GWh. Boundary unverified. Missing observations stay blank.</p><div id="demand"></div><details><summary>Separate annual subscriber consumption</summary><p>Different definition; never merged into monthly demand.</p><div id="annual"></div></details></article>
<article><h2>F · Electricity YoY growth</h2><div class="empty">Not estimable: no verified positive year-ago pairs. No interpolation.</div></article>
<article><h2>G · DFM factor loadings</h2><p>Frozen M0 loadings; no E1 loading was estimated. Dimensionless.</p><div id="loading"></div></article>
<article><h2>H · DFM factor signals</h2><p>Frozen descriptive standardized units, not additive GDP effects.</p><div id="signals"></div></article>
<article><h2>I · Current nowcast references</h2><p>2026Q3; frozen cutoff 2026-10-05. Latest electricity August 2026; collected October 12 and not confirmed available as a vintage at cutoff.</p><div id="now"></div></article>
<article><h2>J · Coverage and release delay</h2><p>June–August 2026 only. September publication not verified. VINTAGE_UNVERIFIED: page-heading dates are evidence, not historical snapshots.</p><div id="coverage"></div><div id="lags"></div></article>
</div><article style="margin-top:20px"><h2>Source evidence</h2><input id="search" placeholder="Filter sources" oninput="sourceTable()" aria-label="Filter sources"><div id="sources"></div><p>Annual subscriber data, consumer deliveries, household bills, system demand and generation are distinct. HET reports and official archive indices were inspected; completeness remains unverified. Electricity is withheld from operational use.</p></article>
<script>const D=__DATA__;
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function table(id,rows,cols){document.getElementById(id).innerHTML='<table><tr>'+cols.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+esc(typeof r[c]==='number'?r[c].toFixed(6):r[c])+'</td>').join('')+'</tr>').join('')+'</table>'}
function bars(id,rows,label,value){const valid=rows.filter(r=>Number.isFinite(r[value]));const max=Math.max(...valid.map(r=>Math.abs(r[value])),1);document.getElementById(id).innerHTML='<svg viewBox="0 0 600 '+Math.max(valid.length*42+30,100)+'" role="img" aria-label="'+esc(value)+'">'+valid.map((r,i)=>'<text x="0" y="'+(i*42+24)+'">'+esc(r[label])+'</text><rect class="bar" x="170" y="'+(i*42+8)+'" width="'+(Math.abs(r[value])/max*300)+'" height="22"><title>'+esc(r[label])+': '+r[value]+'</title></rect><text x="480" y="'+(i*42+24)+'">'+r[value].toFixed(3)+'</text>').join('')+'</svg>'}
function horizons(){bars('hchart',D.metrics.filter(r=>r.horizon===document.getElementById('horizon').value),'model','rmse')}
function history(){let rows=D.history.filter(r=>r.horizon===document.getElementById('histH').value);let qs=[...new Set(rows.map(r=>r.target_quarter))].sort();let values=rows.flatMap(r=>[r.actual,r.prediction]);let lo=Math.min(...values)-.2,hi=Math.max(...values)+.2;let colors=['#fff','#58d9cc','#70a9ff','#ffbf69'];let models=['Actual','PHASE6C_DFM','U_MIDAS','COMBO_50_50'];let svg='<svg viewBox="0 0 600 220" role="img" aria-label="Actual and predicted cumulative YTD GDP growth">';models.forEach((m,j)=>{let points=qs.map((q,i)=>{let r=rows.find(r=>r.target_quarter===q&&(m==='Actual'||r.model===m));let v=m==='Actual'?r.actual:r.prediction;return [60+i*150,170-(v-lo)/(hi-lo)*125,v,q]});svg+='<polyline fill="none" stroke="'+colors[j]+'" stroke-width="2" points="'+points.map(p=>p[0]+','+p[1]).join(' ')+'"/>'+points.map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="4" fill="'+colors[j]+'"><title>'+m+' '+p[3]+': '+p[2]+'%</title></circle>').join('');svg+='<text x="'+(j*145)+'" y="210" style="fill:'+colors[j]+'">'+m+'</text>'});svg+=qs.map((q,i)=>'<text x="'+(45+i*150)+'" y="190">'+q+'</text>').join('')+'<text x="0" y="30">'+hi.toFixed(2)+'%</text><text x="0" y="170">'+lo.toFixed(2)+'%</text></svg>';document.getElementById('history').innerHTML=svg}
function sourceTable(){let q=document.getElementById('search').value.toLowerCase();table('sources',D.sources.filter(r=>(r.source_name+' '+r.finding).toLowerCase().includes(q)),['source_name','http_status','status','finding','source_url'])}
table('summary',D.scores,['model','n','rmse','mae','bias','matched_challenger_origins','comparison_status']);bars('rmse',D.scores,'model','rmse');horizons();history();
bars('demand',D.monthly,'date','electricity_consumption_gwh');table('annual',D.annual,['year','electricity_consumption_gwh']);bars('loading',D.loadings,'indicator','loading');bars('signals',D.signals,'indicator','contribution_or_signal');table('now',D.now,['model','forecast','status']);
document.getElementById('coverage').innerHTML='<div style="display:flex;flex-wrap:wrap;gap:3px">'+D.monthly.map(r=>'<span title="'+r.date+': '+r.observation_status+'" style="width:10px;height:18px;background:'+(r.electricity_consumption_gwh===null?'#405064':'#58d9cc')+'"></span>').join('')+'</div><p class="tip">93 months, left to right: Jan 2019–Sep 2026. Teal = observed; grey = missing. Hover for month.</p>';
table('lags',D.monthly.filter(r=>r.electricity_consumption_gwh!==null),['date','publication_date','vintage_status']);sourceTable();</script></html>'''
    (out/'phase7a_electricity_comparison.html').write_text(text.replace('__DATA__',json.dumps(data).replace('</','<\\/')),encoding='utf8')
